package glitch

import data.glitch_lib

# Keywords indicating potential hardcoded secrets
secret_keywords := {"password", "secret", "secretKey", "token", "credential", "credentials", "auth", "authentication", "key", "passwd", "pwd", "username", "admin", "connection_string", "jdbc", "odbc", "bind_password", "api_key", "api_secret"}

# Check if value is a static literal (not a reference or dynamic call)
is_static_literal(value) {
    value.ir_type == "String"
}

is_static_literal(value) {
    value.ir_type == "Integer"
}

is_static_literal(value) {
    value.ir_type == "Boolean"
}

# Traverse complex structures (Hash, Array) to find static string values containing sensitive patterns
find_static_secret_in_complex(value) {
    walk(value, [path, node])
    node.ir_type == "String"
    regex.match("(?i)(password|secret|token|credential|auth|key|username|admin|connection_string|jdbc|odbc|bind_password|api_key)", node.value)
}

# Check if the attribute name or value indicates a hardcoded secret
check_hardcoded_secret(attr) {
    # Check if attribute name matches a secret keyword
    regex.match(sprintf("(?i).*(%s).*", [concat("|", secret_keywords)]), attr.name)
    is_static_literal(attr.value)
} else {
    # Check if the value is a string containing a connection string with credentials
    attr.value.ir_type == "String"
    regex.match("(?i)(password|pwd|pass)=[^&]+", attr.value.value)
} else {
    # Check complex values (Hash/Array) for static secret strings
    attr.value.ir_type in {"Hash", "Array"}
    find_static_secret_in_complex(attr.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_hardcoded_secret(attr)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Avoid using hardcoded passwords in configuration. (CWE-259)"
    }
}

