package glitch

import data.glitch_lib

# Keywords indicating sensitive authentication attributes
sensitive_keywords := {
    "password", "secret", "secretkey", "token", "credential", "credentials", 
    "auth", "authentication", "key", "passwd", "pwd", "username", "admin", 
    "connection_string", "bind_password", "api_key", "api_secret", "sha512_password"
}

# Check if a key name matches any sensitive keyword (case-insensitive)
is_sensitive_key(key_name) {
    lower_key := lower(key_name)
    sensitive_keywords[_] == lower_key
}

# Check if a value is a hardcoded string (literal, not a reference)
is_hardcoded_string(value) {
    value.ir_type == "String"
    # Ensure it's not empty and not just whitespace
    trim(value.value, " ") != ""
}

# Recursive function to find sensitive hardcoded values in complex structures
find_hardcoded_secrets(node, path, results) {
    # If node is a KeyValue (Variable or Attribute)
    node.ir_type == "Variable"
    key_name := node.name
    is_sensitive_key(key_name)
    is_hardcoded_string(node.value)
    results := {
        "element": node,
        "path": path,
        "key": key_name,
        "value": node.value.value
    }
} else {
    node.ir_type == "Attribute"
    key_name := node.name
    is_sensitive_key(key_name)
    is_hardcoded_string(node.value)
    results := {
        "element": node,
        "path": path,
        "key": key_name,
        "value": node.value.value
    }
} else {
    # If node is a Hash, recurse into its key-value pairs
    node.ir_type == "Hash"
    pair := node.value[_]
    key := pair.key
    value := pair.value
    # Check if the key is sensitive and value is hardcoded string
    key.ir_type == "String"
    is_sensitive_key(key.value)
    is_hardcoded_string(value)
    results := {
        "element": value,
        "path": path,
        "key": key.value,
        "value": value.value
    }
} else {
    # If node is an Array, recurse into its elements
    node.ir_type == "Array"
    element := node.value[_]
    find_hardcoded_secrets(element, path, results)
} else {
    # If node is a Hash, recurse into its nested values
    node.ir_type == "Hash"
    pair := node.value[_]
    value := pair.value
    find_hardcoded_secrets(value, path, results)
}

# Main rule to detect hardcoded passwords across IaC technologies
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables in the unit block
    variable := parent.variables[_]
    results := find_hardcoded_secrets(variable, parent.path, _)

    result := {
        "type": "sec_hard_pass",
        "element": results.element,
        "path": results.path,
        "description": sprintf("Hardcoded password detected for key '%s'. Use environment variables or secret managers instead. (CWE-259)", [results.key])
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check atomic units and their attributes
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Recursively find hardcoded secrets in the atomic unit
    find_hardcoded_secrets(node, parent.path, results)

    result := {
        "type": "sec_hard_pass",
        "element": results.element,
        "path": results.path,
        "description": sprintf("Hardcoded password detected for key '%s'. Use environment variables or secret managers instead. (CWE-259)", [results.key])
    }
}

