package glitch

import data.glitch_lib

# Set of hardcoded keywords related to authentication and secrets based on CWE-259
hardcoded_keywords := {"password", "secret", "secretKey", "token", "credential", "credentials", "auth", "authentication", "key", "passwd", "pwd", "username", "admin", "connection_string", "bind_password", "api_key", "api_secret", "admin_password", "root_password"}

# Check if the attribute value is a static string literal
is_static_string(value) {
    value.ir_type == "String"
}

# Check if the attribute value is a base64 encoded string (static)
is_base64_static(value) {
    value.ir_type == "String"
    regex.match("^[A-Za-z0-9+/]*={0,2}$", value.value)
}

# Check if the attribute name matches any of the hardcoded keywords
is_hardcoded_keyword(name) {
    name in hardcoded_keywords
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for attributes in atomic units
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name matches a hardcoded keyword
    is_hardcoded_keyword(attr.name)

    # Check if the attribute value is a static string literal or base64 encoded
    is_static_string(attr.value) or is_base64_static(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Hard-coded credentials in IaC scripts can be easily extracted by attackers. (CWE-259)"
    }
}

